#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
    double x, y;
};

/* Count the number of cartesian points in each quadrant.
   The vector `points` contains a list of `Point` objects.
   Store the counts in `bins` (order: I, II, III, IV).
   Points that lie on an axis are ignored.
*/
void countQuadrants(const std::vector<Point>& points,
                    std::array<std::size_t, 4>& bins)
{
    // Initialise the output bins.
    bins.fill(0);

    // Parallel region – each thread works on a private copy of the counters.
    #pragma omp parallel
    {
        std::array<std::size_t, 4> local = {0, 0, 0, 0};

        // Distribute the work over the points.
        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const Point& p = points[i];

            if (p.x > 0.0 && p.y > 0.0) {
                ++local[0];               // Quadrant I
            } else if (p.x < 0.0 && p.y > 0.0) {
                ++local[1];               // Quadrant II
            } else if (p.x < 0.0 && p.y < 0.0) {
                ++local[2];               // Quadrant III
            } else if (p.x > 0.0 && p.y < 0.0) {
                ++local[3];               // Quadrant IV
            }
            // Points on the axes are ignored.
        }

        // Combine each thread's private counters into the shared result.
        #pragma omp critical
        {
            for (int q = 0; q < 4; ++q) {
                bins[q] += local[q];
            }
        }
    }
}
